<?php $items=array('เลขครุภัณฑ์'=>$a['asset_no'],'ปีงบ'=>$a['budget_year'],'ชื่อครุภัณฑ์'=>$a['property_name'],'ประเภท'=>$a['property_type'],'ยี่ห้อ / รุ่น'=>trim($a['brand'].' '.$a['model']),'Serial Number'=>$a['serial_no'],'หน่วยงาน'=>$a['department'],'สถานที่'=>$a['location'],'ผู้รับผิดชอบ'=>$a['responsible_person'],'วันที่จัดซื้อ'=>$a['purchase_date'],'วันหมดประกัน'=>$a['warranty_date'],'ผู้จำหน่าย'=>$a['vendor'],'สถานะ'=>$a['status']);foreach($items as $k=>$v):?><div class="item"><span><?php echo property_e($k); ?></span><strong><?php echo property_e($v?$v:'-'); ?></strong></div><?php endforeach; ?><div class="item full"><span>ราคา</span><strong class="price">฿<?php echo property_currency($a['price']); ?></strong></div><div class="item full"><span>หมายเหตุ</span><strong><?php echo nl2br(property_e($a['note']?$a['note']:'-')); ?></strong></div></div><div class="footer"><span>งานทรัพย์สิน โรงพยาบาลภักดีชุมพล</span><span>พิมพ์เมื่อ <?php echo date('d/m/Y H:i'); ?></span></div></body></html>
